"""Payment handling for the checkout flow."""


SUPPORTED_METHODS = ("card", "bank_transfer")


def create_payment(checkout, method="card"):
    """Create a payment for an existing pending checkout.

    Expects the dict returned by create_checkout (or an equivalent payload)
    and returns a payment result.
    """
    if not isinstance(checkout, dict):
        raise ValueError("A checkout payload is required")
    if checkout.get("status") != "pending_payment":
        raise ValueError("The checkout is not awaiting payment")
    amount_cents = checkout.get("amount_cents")
    if not isinstance(amount_cents, int) or amount_cents < 1:
        raise ValueError("The checkout amount is invalid")
    if method not in SUPPORTED_METHODS:
        raise ValueError("Unsupported payment method")
    return {"status": "ok", "amount_cents": amount_cents, "method": method}

"""Standard-library HTTP entry point; no external package installation."""
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from .checkout import create_checkout
from .payments import create_payment

WEB_ROOT = Path(__file__).resolve().parent.parent / "web"


def _read_json(handler):
    size = int(handler.headers.get("Content-Length", "0"))
    if size > 65536:
        raise ValueError("Request too large")
    return json.loads(handler.rfile.read(size))


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/api/status":
            return self.reply(200, {"service": "checkout", "version": "2.0"})
        if self.path in ("/", "/app.js"):
            name = "index.html" if self.path == "/" else "app.js"
            body = (WEB_ROOT / name).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", "text/html" if name.endswith("html") else "text/javascript")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        self.reply(404, {"error": "Not found"})

    def do_POST(self):
        if self.path == "/api/checkout":
            try:
                payload = _read_json(self)
                result = create_checkout(payload["cart"], payload.get("method", "card"))
                self.reply(200, result)
            except (KeyError, ValueError, TypeError, json.JSONDecodeError) as exc:
                self.reply(400, {"error": str(exc)})
            return
        if self.path == "/api/pay":
            try:
                payload = _read_json(self)
                checkout = payload.get("checkout")
                if checkout is None:
                    checkout = create_checkout(payload["cart"], payload.get("method", "card"))
                result = create_payment(checkout, payload.get("method", "card"))
                self.reply(200, result)
            except (KeyError, ValueError, TypeError, json.JSONDecodeError) as exc:
                self.reply(400, {"error": str(exc)})
            return
        self.reply(404, {"error": "Not found"})

    def reply(self, status, value):
        body = json.dumps(value).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def main():
    ThreadingHTTPServer(("127.0.0.1", 8080), Handler).serve_forever()


if __name__ == "__main__":
    main()

